-- test/seed/rp33.sql — 승계 완료 스냅샷(프로젝트 RMS, 설계서 §13.3, TODO T7.10)
-- 생성: pnpm --filter @termflow/server ddl:rp33 (승계 러너 1~11 결과 DB에서). 직접 수정 금지 — 러너 결과가 바뀌면 다시 생성
-- 용도: DDL 골든 파일(pnpm test -- ddl-golden: JSON을 읽어 TableModel 조립) · DB 테스트(빈 DB에 그대로 실행)
-- 실행 전제: 0001_baseline 적용 직후의 빈 DB. ID는 원본 그대로, IDENTITY는 적재 후 최댓값으로 맞춘다
-- =====================================================================

-- tf_project: 1행
INSERT INTO tf_project OVERRIDING SYSTEM VALUE
SELECT * FROM json_populate_recordset(NULL::tf_project, $json$[
{"kind":"PROJECT","status":"ACTIVE","created_at":"2026-09-29T11:50:13","created_by":"MIGRATION","created_ip":null,"project_id":3,"project_nm":"연구관리시스템(이관)","updated_at":"2026-09-29T11:50:13","updated_by":"MIGRATION","updated_ip":null,"description":"gen-table에서 승계한 RP_ 테이블 33개 · 템플릿 'TermFlow 기본 표준 v1'에서 생성","project_key":"RMS","default_dialect":"POSTGRESQL","default_col_set_id":null,"include_default_cols":true,"copied_from_project_id":null}
]$json$);
SELECT setval(pg_get_serial_sequence('tf_project', 'project_id'), (SELECT coalesce(max(project_id), 1) FROM tf_project));

